import java.nio.file.*;import java.time.*;import java.time.format.*;import java.util.*;import java.util.stream.*;
public class ExamEngine{public static void main(String[]a)throws Exception{Scanner s=new Scanner(System.in);List<String>w=Files.readAllLines(Paths.get("words.txt")),d=Files.readAllLines(Paths.get("defs.txt"));List<Integer>x=IntStream.range(0,w.size()).boxed().collect(Collectors.toList());Collections.shuffle(x);System.out.println("Please enter your name");String n=s.nextLine().toLowerCase(),r=n+"\r\n"+LocalDateTime.now().format(DateTimeFormatter.ofPattern("MM/dd/yyyy HH:mm:ss"))+"\r\nCorrect Words:\r\n";int c=0;System.out.println("Welcome to the spelling test "+n+" here is your first word and the remaining "+(w.size()-1)+" will follow\n");for(int i:x){System.out.println(d.get(i)+i);if(s.nextLine().equalsIgnoreCase(w.get(i))){System.out.println("Correct!\n");r+=w.get(i)+"\r\n";c++;}else System.out.println("Incorrect.\n");}Files.write(Paths.get(n+".txt"),r.getBytes());System.out.println(n+" your score was "+c+" of "+w.size()+"!");}}
